def b(label,cls='',disabled=False):return f'<button class="{cls}"'+(' disabled' if disabled else '')+f'>{label}</button>'
def header(dark=False,compact=False):return ('<header class="header"><div class="brand"><img src="assets/leqad-official-horizontal-light-v1.svg" alt="Leqad approved mark"></div><div class="row">'+b('≡','quiet')+b('−','quiet')+b('×','quiet')+'</div></header>').replace('horizontal-light', 'symbol-light' if compact else 'horizontal-dark' if dark else 'horizontal-light')
def context():return '<div class="context"><p class="eyebrow">Your First Sketch · Step 4 of 8</p><h3>Draw a Corner Rectangle</h3><p class="small muted">3 steps completed · CAD work unverified</p><div class="rule"><span></span></div></div>'
def footer(primary='Mark done',ev='Not checked. Marking done records your report.',right='Pause'):return '<footer class="footer"><p class="small muted">'+ev+'</p>'+b(primary,'primary')+'<div class="row">'+b('Back','quiet')+b(right,'quiet')+'</div></footer>'
def panel(body,foot=None,cls='',state='Capture off',ask=False):return '<div class="panel '+cls+'">'+header(dark='dark' in cls.split())+f'<div class="session"><span>Chrome · Window 1</span><span>{state}</span></div><nav class="nav">'+b('Learn','active' if not ask else '')+b('Ask','active' if ask else '')+'</nav><div class="body">'+body+'</div>'+(footer() if foot is None else foot)+'</div>'
def helpbox():return '<section class="help">'+b('Help −','quiet help-toggle')+'<div class="topics">'+b('Hint','selected')+b('Detailed guidance')+b('Why it matters')+b('Unable to verify')+'</div><div class="help-content" tabindex="0" aria-label="Hint content"><p>Corner Rectangle uses two opposite corners. Start with one corner, then place the opposite corner.</p><p>Use the tool name to distinguish it from Center Rectangle, which starts at the center.</p>'+b('More help','quiet')+'</div></section>'
def notes(*pairs):return '<aside class="notes">'+''.join('<p><strong>'+a+'</strong>'+v+'</p>' for a,v in pairs)+'</aside>'
boards=[]
def add(num,title,desc,scene):boards.append(f'<section class="board" id="board-{num:02}"><div class="board-title"><div class="design-label">Design mockup {num:02} · not a running desktop app</div><h2>{title}</h2><p>{desc}</p></div><div class="scene">{scene}</div></section>')
selection='<div class="panel selection">'+header()+'<div class="body"><h2>Learn alongside your CAD workspace</h2><p>Choose a window for this session. Written lessons work without screen capture.</p><div class="stack"><div class="window-choice"><span class="radio"></span><div><strong>Chrome · Window 1</strong><p class="small muted">CAD context not checked</p></div></div><div class="window-choice"><span class="radio"></span><div><strong>FreeCAD · Window 1</strong><p class="small muted">Desktop support not validated</p></div></div></div><div class="row">'+b('Identify window','quiet')+b('Refresh list','quiet')+'</div><p class="small muted">Window names stay on this device. No images captured.</p><div class="stack select-actions">'+b('Use selected window','primary',True)+b('Use written lessons','quiet')+'</div></div></div>'
add(1,'Select a CAD window','Illustrative window list. Enumeration is a future host capability; these entries are not detected applications.',selection+notes(('560 × 620 DIP','A single list, one selected window, one primary action.'),('No implicit access','Choosing a window establishes a binding, not capture consent or CAD recognition.'),('Private identification','Identify window may reveal the title locally. Titles and identifiers never enter saved reports.')))
consent='<div class="panel selection">'+header()+'<div class="body"><p class="eyebrow">Optional visual help</p><h2>Allow visual help for this session?</h2><p><strong>Chrome · Window 1</strong></p><p>Only the window you selected. When you request SHOW, Leqad may inspect its interface controls and capture images of that window for up to 5 seconds.</p><ul class="consent-list"><li>No control inspection or capture between requests.</li><li>Images stay in memory; no saving or uploading.</li><li>Focus or permission changes stop the request.</li></ul><p class="small muted">Control recognition may still be unavailable. You can revoke access in Settings.</p><div class="stack select-actions">'+b('Allow for this session','primary')+b('Continue without capture','quiet')+'</div></div></div>'
add(2,'Capture consent','Proposed consent screen. Offer it only when a real selected-window capture provider can honor every statement.',consent+notes(('Consent is optional','Declining retains written lessons and authored local Ask.'),('No background default','SHOW starts one bounded request. Relaunch, new window, and disconnect require fresh consent.'),('OS permission comes next','An OS access prompt cannot substitute for this explanation.')))
normal=context()+'<div class="instruction"><p class="eyebrow">Create the rectangular profile</p><p>In Sketch, choose Corner Rectangle. Place one corner, then the opposite corner.</p></div>'+b('Help +','quiet help-toggle')+'<p class="small muted">Visual guidance for this control isn’t available yet.</p>'
add(3,'Your lesson, kept close','Default written-guidance state. The panel does not claim current Sketch context or working desktop recognition.',panel(normal)+notes(('365 × 600 DIP','16px content insets. No decorative shadow. Native move/size remains accessible.'),('One primary action','Mark done is explicitly self-reported. It is never a geometry PASS.'),('Honest instructions','“In Sketch” describes where to act; it does not say Sketch has been observed.')))
add(4,'Progressive help','The same 365 × 600 window. One help topic at a time; the help area would be under 126px, so one body scroller keeps the full explanation reachable.',panel(context()+'<p class="instruction">Place one corner, then the opposite corner.</p>'+helpbox(),cls='overflow-mode')+notes(('Context remains reachable','At this default height the context scrolls with help. Evidence and the primary action stay in the footer.'),('No automatic growth','Opening help does not expand the native window over CAD.'),('Keyboard access','The scrolling content is focusable. Escape closes help and returns to its disclosure.')))
ask=context()+'<p class="eyebrow">Local prototype · no AI connected</p><div class="ask-scroll">'+b('Why use Corner Rectangle?','question selected')+b('What can Leqad verify?','question')+'<section class="answer"><p class="eyebrow">Local example</p><p>Corner Rectangle uses two opposite corners. It suits this lesson’s corner-based rectangular profile. Center Rectangle starts from a center point instead.</p><p class="small muted">This explanation does not check your sketch.</p></section></div>'
add(5,'Ask, with a clear boundary','Authored examples only. No free-text chat, network request, simulated typing, or invented observation.',panel(ask,footer('Return to Learn','Local examples do not change progress.'),ask=True)+notes(('Step context persists','Questions belong to the current step. A step change clears the selected answer.'),('No implied AI','Prototype and Local example labels remain visible to readers and assistive technology.')))
schematic='<div class="schematic"><p class="schematic-label">SCHEMATIC ONLY · no Onshape or FreeCAD screenshot</p><div class="toolbar"><div class="target">Illustrative control A</div><div class="target outline">Illustrative target</div><div class="target">Control B</div></div><p class="workspace-note">This blank region represents the selected workspace. Control identities and positions are invented solely to explain overlay appearance.</p><div class="mini-panel"><p class="eyebrow">Hypothetical validated target</p><p>Control highlighted. Perform the action yourself.</p><p class="small">Geometry not checked.</p></div></div>'
add(6,'One temporary, non-interfering outline','Future supported state only. Current PR #17 does not establish this capability. The panel and outline are separate native windows.',schematic+notes(('No overlay controls','A square outline, no fill, label, button, flashing, or focus interception.'),('Native pass-through required','CSS pointer-events alone cannot prove CAD receives input.'),('Expires on invalidation','Focus loss, changed tab, stale evidence, permissions, layout changes, or request timeout clear it.')))
unknown=context()+'<div class="status"><p><strong>Unable to locate a reliable target</strong></p><p class="small">No highlight shown. CAD geometry has not been checked.</p></div><p>In Sketch, open the Rectangle group and choose Corner Rectangle by name.</p>'+b('Read detailed guidance','quiet')+b('Try SHOW again')
add(7,'Useful uncertainty','Hypothetical failed request from an available adapter. An unsupported build omits Retry and offers written instructions.',panel(unknown,state='Capture on request')+notes(('No guessing','Missing, stale, and duplicate results stay unknown.'),('Bounded retry','One request at a time. New requests cancel old ones and recheck context and permission.')))
paused=context()+'<div class="status"><h3>Paused</h3><p>No observation running.</p></div><p>Your lesson stays here. Resume when you are ready to continue.</p><p class="small muted">Resuming does not start capture. Visual help always needs a new request.</p>'
add(8,'Pause without losing your place','Cancel observation and highlights immediately; preserve lesson history.',panel(paused,footer('Resume lesson','CAD work remains unverified.','End session'),state='Observation paused')+notes(('Explicit resume','No capture or highlight resumes automatically.'),('Memory only','Existing session consent may remain while paused. End session revokes it.')))
disconnected=context()+'<div class="status"><h3>Window unavailable</h3><p>The selected window is no longer available.</p></div><p>Your lesson progress is retained. Choose a window again or continue with written guidance.</p>'+b('Continue with written guidance','quiet')
add(9,'Recover from disconnection','A closed or replaced window revokes its binding and capture consent. Do not silently select a similar window.',panel(disconnected,footer('Select a window','Capture stopped. Select and allow again if needed.','End session'),state='Disconnected')+notes(('No stale attachment','A reused window handle must not revive the session.'),('Separate progress','The lesson can resume without preserving a capture permission or OS identifier.')))
settings='<h3>Settings</h3><div class="settings" tabindex="0" role="region" aria-label="Session and appearance settings"><div class="stack"><p class="eyebrow">Visual access and recovery</p>'+b('Stop / revoke visual access')+b('Change window')+b('Reset panel position')+b('Report misaligned highlight')+'</div><p class="small muted" style="margin-top:12px">Scroll for appearance and accessibility</p><div class="settings-row"><span>Appearance</span><select aria-label="Appearance"><option>System</option><option>Light</option><option>Dark</option></select></div><div class="settings-row"><span>Text size</span><select aria-label="Text size"><option>100%</option><option>200%</option></select></div><div class="settings-row"><span>Keep panel visible</span><span>On</span></div><div class="settings-row"><span>Reduced motion</span><span>Follow Windows</span></div><div class="settings-row"><span>Default help</span><span>HINT</span></div></div>'

add(10,'Settings in the same window','Settings are a single returnable view. Representative values, not connected native settings.',panel(settings,'<footer class="footer">'+b('Back to lesson','primary')+'</footer>',state='Capture on request')+notes(('Few preferences','No diagnostics dashboard or account setup.'),('Immediate revoke','Revoke cancels in-flight work and discards pending frames.'),('No automatic report','Reporting clears the highlight first. Any export requires local preview and explicit action.')))
add(11,'Compact screen fallback','320 × 400 DIP. One body scrollbar replaces independent help scrolling; the step and action remain reachable.',panel(context()+'<p>Place one corner, then the opposite corner.</p>'+helpbox(),cls='short')+notes(('One scroller','Short-height mode removes the nested help scroller.'),('Text stays readable','No shrink-to-fit. At extreme enlargement, the entire content can scroll, including the footer.'),('Resizing is local','Never move or resize CAD to make room for Leqad.')))
add(12,'Dark appearance','Same hierarchy, spacing, and approved logo. Hover uses a dark surface with readable light text.',panel(context()+'<p>Place one corner, then the opposite corner.</p>'+helpbox(),cls='dark overflow-mode')+notes(('Measured palette','Static palette ratios are documented separately. Actual Electron hover and focus remain future tests.'),('Logo preserved','Official circular emblem and custom wordmark; exact source paths. Russet center #793327.')))
displays='<div class="stack"><div class="row"><div class="display"><p class="eyebrow">Display A · 100% scale</p><p class="small">Logical origin −1920, 0</p><div class="mini-panel"><strong>Selected CAD window</strong><p class="small">Fresh mapping required after moving.</p></div></div><div class="display two"><p class="eyebrow">Display B · 150% scale</p><p class="small">Logical origin 0, 0</p><div class="mini-panel"><strong>Leqad teaching panel</strong><p class="small">Move independently. Keep within work area.</p></div></div></div><p class="small">Layout schematic only. On display removal: stop visual help, restore Leqad onto an available work area, then wait for a new request.</p></div>'
add(13,'Multiple displays, one valid context','Conceptual display arrangement. Device pixels and logical placement must remain separate.',displays)
collapsed='<div class="panel collapsed">'+header(compact=True)+'<div class="row small"><span>Step 4 of 8</span>'+b('Expand','quiet')+'</div></div>'
add(14,'Collapse preserves your place','280 × 112 DIP. The menu retains Pause/Resume, movement, and exit. Collapse preserves the previous active or paused lesson state.',collapsed+notes(('No background observation','Collapse cancels any active request. Expand never restarts capture.'),('Current step retained','Restore the same lesson with its evidence labels.')))
unavailable=context()+'<div class="status"><h3>Visual help unavailable</h3><p>Window capture isn’t available in this build.</p></div><p>Follow the written steps. You can still use hints and mark steps done yourself.</p>'+b('Read a hint','quiet')+'<p class="small muted">No window images are being captured.</p>'
add(15,'Permission and capability fallback','Use “Capture not allowed” after denial. Use “Visual help unavailable” when the provider does not exist.',panel(unavailable)+notes(('No fake consent','Do not present a working Allow button when there is no provider.'),('Lesson remains usable','HINT and local examples require neither capture nor verified edit permissions.')))

def guidance(permitted):
 return context()+'<section class="help">'+b('Help −','quiet help-toggle')+'<p class="eyebrow">Detailed guidance</p><div class="row">'+b('HINT')+b('SHOW','',not permitted)+b('GUIDE','',True)+'</div><p class="small muted">GUIDE is not available for this control.</p>'+('' if permitted else '<p class="small">SHOW needs your permission for this session.</p>'+b('Set up visual help','quiet'))+'<div class="help-content" tabindex="0"><p>In Sketch, open the Rectangle group. Choose Corner Rectangle by its name.</p><p>Place one corner, then the opposite corner.</p></div></section>'
add(16,'Detailed guidance and consent gating','Hypothetical adapter-supported states only. Left: consent granted, SHOW available. Right: permission needed, using the single-body scroll fallback so written guidance stays reachable. No current desktop support is claimed.',panel(guidance(True),state='Capture on request')+panel(guidance(False),cls='overflow-mode'))
waiting=context()+'<div class="status"><h3>Return to your CAD window</h3><p>Use Alt+Tab or your usual window switcher. Leqad will not click or switch windows for you.</p></div><p class="small">Request expires in 10 seconds. Nothing is being captured yet. On expiry, request SHOW again to retry.</p>'
inspecting=context()+'<div class="status"><h3>Inspecting the selected window</h3><p>Looking for the requested control. No reliable target yet.</p></div><p class="small">Stops within 5 seconds or sooner if focus or permission changes.</p><p class="small muted">Images stay in memory. Geometry is not checked.</p>'
add(17,'SHOW handoff and inspection','Prototype timing, subject to real usability tests. Hypothetical request states. Successful CAD focus and identity validation end the pending deadline and start a separate five-second observation ceiling.',panel(waiting,footer('Cancel request','No lesson progress changes.','Pause'),state='Waiting for CAD')+panel(inspecting,footer('Cancel request','No lesson progress changes.','Pause'),state='Inspecting on request'))
ack='<div class="context"><p class="eyebrow">Your First Sketch · Step 1 of 8</p><h3>Before you begin</h3></div><div class="status"><p>Instruction acknowledged.</p></div><p>You are ready to read the next step. No CAD operation has been verified.</p>'
done=context().replace('3 steps completed','4 steps completed').replace('<span></span>','<span style="width:50%"></span>')+'<div class="status"><h3>Marked done by you</h3><p>CAD work unverified.</p></div><p>You reported completing this step. Continue when you are ready.</p>'
summary='<h3>Lesson completed</h3><p>8 steps completed. CAD work is not independently verified.</p><p class="small">Scroll to review all 8 steps</p><div class="ask-scroll summary-scroll" tabindex="0" role="region" aria-label="All eight step outcomes"><p class="small">Illustrative outcome summary</p>'+''.join('<p class="small"><strong>'+label+'</strong><br>'+outcome+'</p>' for label,outcome in [('1 · Introduction','Acknowledged'),('2 · Reference plane','Self-reported'),('3 · Start Sketch','Self-reported'),('4 · Corner Rectangle','Self-reported'),('5 · Dimensions','Self-reported'),('6 · Finish Sketch','Self-reported'),('7 · Understand the result','Acknowledged'),('8 · Independent practice','Self-reported')])+'</div>'
add(18,'Acknowledgement, self-report, and completion','Illustrative outcome states only. Actual text must derive from stored engine outcomes; never hardcode a model-verification result.',panel(ack,footer('Next step','Acknowledgement only.'))+panel(done,footer('Next step','No geometry check performed.'))+panel(summary,footer('Review steps','Review keeps progress. Restart requires confirmation.','End session')))
resume='<div class="panel selection">'+header()+'<div class="body"><p class="eyebrow">Saved on this device</p><h2>Continue Your First Sketch?</h2><p>Step 4 of 8 · 3 steps completed</p><p>Saved lesson progress does not describe your current CAD model.</p><p class="small muted">Select a window again if you want visual help. Capture permission is not restored.</p><div class="stack select-actions">'+b('Resume lesson','primary')+b('Start again','quiet')+'</div><p class="small muted">Start again asks for confirmation before resetting this lesson.</p></div></div>'
add(19,'Resume a lesson','Saved progress and preferences are distinct from the new desktop session. This board assumes a successful previous save.',resume+notes(('No restored capture','Session bindings and permissions are never loaded as active from disk.'),('Confirmed reset','Cancel or Reset lesson. Preferences remain unchanged.')))

intro='''<div class="gallery-head"><p class="design-label">Leqad · Phase 1B · design for owner review</p><h1>Compact Companion</h1><p>Standalone Windows teaching panel. These are static design boards, not a working Electron application. All window entries and highlighted targets are illustrative. No real CAD capture, AI, or geometry verification is demonstrated.</p><p>Approved artwork, Space Grotesk, and Manrope are bundled locally. No external resources or application scripts are loaded.</p><nav>'''+''.join(f'<a href="#board-{i:02}">{i:02}</a>' for i in range(1,20))+'''</nav></div>'''
(P/'mockups.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Leqad desktop Compact Companion design</title><style>'+css+'</style><body>'+intro+''.join(boards)+'</body></html>')
